                old = D[a][b] + D[c][d]
                new = D[a][c] + D[b][d]
                if new < old:
                    rt[i:k + 1] = rt[i:k + 1][::-1]
                    iters += 1
                    improved = True
        return improved

    heavy = (n <= 140) or (demand_pressure < 0.97 and desc.get('corridor', 0.05) < 0.2)
    max_intra_2opt = 50 if heavy else 25

    for idx in range(len(routes)):
        if len(routes[idx]) >= 4:
            two_opt_route(routes[idx], max_intra_2opt)
            loads[idx] = route_load(routes[idx])

    # Inter-route relocate (deterministic first improvement)
    def inter_relocate(max_inter_ops):
        rcount = len(routes)
        ops = 0
        for i in range(rcount):
            if not routes[i]:
                continue
            rt_i = routes[i]
            l_i = len(rt_i)
            # scan ends inward deterministically
            order = []
            for t in range(l_i):
                order.append(t if t % 2 == 0 else (l_i - 1 - t))
            order = [u for u in order if 0 <= u < l_i]

            for j in range(rcount):
                if i == j or not routes[j]:
                    continue
                rt_j = routes[j]
                m = len(rt_j)
                cap_rem = cap - loads[j]
                if cap_rem <= 0:
                    continue

                for pos_i in order:
                    cust_i = rt_i[pos_i]
                    di = demand[cust_i]
                    if di > cap_rem:
                        continue

                    for p in range(m + 1):
                        # neighbors around insertion in j
                        if m == 0:
                            left, right = depot, depot
                        elif p == 0:
                            left, right = depot, rt_j[0]
                        elif p == m:
                            left, right = rt_j[m - 1], depot
                        else:
                            left, right = rt_j[p - 1], rt_j[p]

                        # old removal delta from i
                        li = rt_i
                        if len(li) == 1:
                            old_remove_i = D[depot][cust_i] + D[cust_i][depot]
                        else:
                            if pos_i == 0:
                                a, b, c = depot, cust_i, li[1]
                                old_remove_i = D[a][b] + D[b][c] - D[a][c]
                            elif pos_i == len(li) - 1:
                                a, b, c = li[-2], cust_i, depot
                                old_remove_i = D[a][b] + D[b][c] - D[a][c]
                            else:
                                a, b, c = li[pos_i - 1], cust_i, li[pos_i + 1]
                                old_remove_i = D[a][b] + D[b][c] - D[a][c]

                        # insertion cost in j
                        if m == 0:
                            old_insert_j = 0
                        else:
                            old_insert_j = D[left][right]
                        new_insert_j = D[left][cust_i] + D[cust_i][right]
                        delta = (new_insert_j - old_insert_j) - old_remove_i

                        if delta < 0:
                            # apply move
                            rt_i.pop(pos_i)
                            loads[i] -= di
                            rt_j.insert(p, cust_i)
                            loads[j] += di
                            return True
                        ops += 1
                        if ops >= max_inter_ops:
                            return False
        return False

    max_inter_ops = 300 if heavy else 120
    while inter_relocate(max_inter_ops):
        # update loads if route became empty; keep deterministic loop bound via ops in function
        for idx in range(len(routes)):
            if routes[idx]:
                loads[idx] = route_load(routes[idx])

    # Final feasibility repair: split any remaining over-cap routes; remove empties
    out_routes = []
    out_loads = []
    for rt in routes:
        if not rt:
            continue
        if route_load(rt) <= cap:
            out_routes.append(rt)
            out_loads.append(route_load(rt))
        else:
            parts = split_route(rt)
            for p in parts:
                if p:
                    out_routes.append(p)
                    out_loads.append(route_load(p))
    routes = out_routes

    # Ensure all customers served exactly once; if something still missing, add as singleton
    served = set()
    for rt in routes:
        for x in rt:
            served.add(x)
    missing = [x for x in customers if x not in served]
    if missing:
        for x in missing:
            routes.append([x])

    # Remove duplicates by keeping first occurrence
    seen = set()
    final_routes = []
    for rt in routes:
        nr = []
        for x in rt:
            if x not in seen:
                nr.append(x)
                seen.add(x)
        if nr:
            final_routes.append(nr)

    return final_routes
